import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int[] l = new int[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            l[i] = Integer.parseInt(st.nextToken());
        }
        int len1 = n / 2;
        int len2 = n - len1;
        int[] half1 = Arrays.copyOfRange(l, 0, len1);
        int[] half2 = Arrays.copyOfRange(l, len1, n);
        int limit1 = 1 << len1;
        int limit2 = 1 << len2;
        List<Integer> subsetSums1 = new ArrayList<>();
        for (int mask = 0; mask < limit1; mask++) {
            int total = 0;
            for (int bit = 0; bit < len1; bit++) {
                if ((mask & (1 << bit)) != 0) {
                    total += half1[bit];
                }
            }
            subsetSums1.add(total % m);
        }
        List<Integer> subsetSums2 = new ArrayList<>();
        for (int mask = 0; mask < limit2; mask++) {
            int total = 0;
            for (int bit = 0; bit < len2; bit++) {
                if ((mask & (1 << bit)) != 0) {
                    total += half2[bit];
                }
            }
            subsetSums2.add(total % m);
        }
        Collections.sort(subsetSums1);
        Collections.sort(subsetSums2);
        int maxMod = 0;

        for (int s : subsetSums1) {
            int target = m - s;
            int candidate = binarySearch(subsetSums2, target);
            maxMod = Math.max(maxMod, (s + candidate) % m);
        }
        System.out.println(maxMod);
    }

    private static int binarySearch(List<Integer> arr, int val) {
        int left = 0;
        int right = arr.size() - 1;
        int res = 0;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (arr.get(mid) < val) {
                res = arr.get(mid);
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return res;
    }
}
